package com.flint.peakfocus.core.datastore

import com.flint.peakfocus.core.model.*
import org.junit.Assert.*
import org.junit.Test

class ProtectionLifecycleCodecTest {
    // Literal pre-change v2 event, including a pending Open end, not generated by today's writer.
    private val legacy = "P|2\nM|1000%7C100%7Cboot|2000%7C1100%7Cboot|0|false|0|1||0|1\nC\nR\n" +
        "E|break-ended:op|op|BREAK_ENDED|session-a|2000%7C1100%7Cboot|op||EXPIRED||4|true\n" +
        "L|credit-op|app|1000%7C100%7Cboot|300000"

    @Test fun PC_69_PC_70_v2EventAndPendingCreditMigrateWithoutInventingConfidenceOrObservation() {
        val decoded = ProtectionLedgerCodec.decode(legacy)
        val event = decoded.outbox.values.single()
        assertTrue(event.timeUncertain)
        assertNull(event.timeConfidence)
        assertNull(event.observedAtEpochMs)
        assertFalse(event.reconciled)
        assertEquals(300_000L, decoded.pendingCreditEnds.getValue("credit-op").lifetime.durationMs)
        val upgraded = ProtectionLedgerCodec.encode(decoded)
        assertTrue(upgraded.startsWith("P|3\n"))
        assertEquals(decoded, ProtectionLedgerCodec.decode(upgraded))
    }

    @Test fun PC_54_PC_55_allEventKindsRoundTripExplicitConfidenceObservationAndReconciliation() {
        val initial = ProtectionLedgerCodec.decode(legacy).copy(pendingCreditEnds = emptyMap())
        for (kind in ProtectionLifecycleKind.entries) for (confidence in listOf(
            ProtectionEventTimeConfidence.Certain, ProtectionEventTimeConfidence.Uncertain("same_boot_drift"),
            ProtectionEventTimeConfidence.Uncertain("unknown_boot"), ProtectionEventTimeConfidence.Uncertain("reboot_without_anchor"))) {
            val ended = kind in setOf(ProtectionLifecycleKind.BREAK_ENDED, ProtectionLifecycleKind.ACCESS_ENDED)
            val event = initial.outbox.values.single().copy(kind = kind,
                grantId = if (kind == ProtectionLifecycleKind.PASS_COMMITTED) null else "op",
                untilEpochMs = if (ended) null else 302_000,
                breakEndReason = if (ended) ProtectionBreakEndReason.EXPIRED else null,
                timeConfidence = confidence, timeUncertain = confidence is ProtectionEventTimeConfidence.Uncertain,
                observedAtEpochMs = 10_000, reconciled = ended)
            val state = initial.copy(outbox = mapOf(event.id to event))
            assertEquals(state, ProtectionLedgerCodec.decode(ProtectionLedgerCodec.encode(state)))
        }
    }

    @Test fun PC_70_malformedOrUnknownConfidenceCannotSilentlyBecomeCertain() {
        val state = ProtectionLedgerCodec.decode(legacy)
        val event = state.outbox.values.single().copy(timeConfidence = ProtectionEventTimeConfidence.Uncertain("same_boot_drift"),
            observedAtEpochMs = 10_000, reconciled = true)
        val wire = ProtectionLedgerCodec.encode(state.copy(outbox = mapOf(event.id to event)))
        for (bad in listOf(
            wire.replace("|uncertain|same_boot_drift|", "|future|same_boot_drift|"),
            wire.replace("|uncertain|same_boot_drift|", "|uncertain||"),
            wire.replace("|uncertain|same_boot_drift|", "|certain||"), // legacy flag contradicts confidence
            wire.replace("|10000|uncertain|", "||uncertain|"),
            wire.replace("|uncertain|same_boot_drift|", "||same_boot_drift|"),
            wire.replace("|uncertain|same_boot_drift|", "|uncertain|a.b.c|"),
            wire.replace("|true|10000|", "|true|-1|"),
            wire.replace("P|3", "P|4"),
        )) {
            try { ProtectionLedgerCodec.decode(bad); fail("Invalid confidence accepted") }
            catch (failure: StorageUnavailableException) {
                assertTrue(failure.reason in setOf(StorageFailure.CORRUPT, StorageFailure.UNSUPPORTED_VERSION))
            }
        }
    }
}
